import { expect, test } from "vitest";
import { getActivityHeatmap } from "../../src/components/home/activityHeatmap";
import { SnapshotPeriod } from "../../src/components/home/homeStatistics";

const timestamp = (year: number, month: number, day: number, hour = 0) => new Date(year, month, day, hour).getTime() / 1000;

// Generated by Codex and not thoroughly checked for correctness.
test("Month buckets clip calendar weeks to the range and count distinct active days", () => {
  const result = getActivityHeatmap([
    { creationTimeSeconds: timestamp(2026, 9, 1, 10) },
    { creationTimeSeconds: timestamp(2026, 9, 1, 11) },
    { creationTimeSeconds: timestamp(2026, 9, 4, 23) },
    { creationTimeSeconds: timestamp(2026, 9, 5) },
    { creationTimeSeconds: timestamp(2026, 9, 30, 23) },
    { creationTimeSeconds: timestamp(2026, 9, 31) },
  ], { startTimeSeconds: timestamp(2026, 9, 1), endTimeSeconds: timestamp(2026, 9, 31) }, SnapshotPeriod.MONTH);
  expect(result.granularity).toBe("week");
  expect(result.data.map((cell) => cell.value)).toEqual([3, 1, 0, 0, 1]);
  expect(result.data[0].label).toBe("Thu Oct 01 2026 – Sun Oct 04 2026: 3 submissions · 2/4 active days");
  expect(result.data[4].label).toBe("Mon Oct 26 2026 – Fri Oct 30 2026: 1 submission · 1/5 active days");
});

// Generated by Codex and not thoroughly checked for correctness.
test("Year buckets include partial months and zero-activity months across a year boundary", () => {
  const result = getActivityHeatmap([
    { creationTimeSeconds: timestamp(2025, 9, 31) },
    { creationTimeSeconds: timestamp(2026, 9, 30, 23) },
  ], { startTimeSeconds: timestamp(2025, 9, 31), endTimeSeconds: timestamp(2026, 9, 31) }, SnapshotPeriod.YEAR);
  expect(result.granularity).toBe("month");
  expect(result.data).toHaveLength(13);
  expect(result.data[0].label).toBe("Fri Oct 31 2025 – Fri Oct 31 2025: 1 submission · 1/1 active days");
  expect(result.data[4].label).toBe("Sun Feb 01 2026 – Sat Feb 28 2026: 0 submissions · 0/28 active days");
  expect(result.data[12].value).toBe(1);
});

// Generated by Codex and not thoroughly checked for correctness.
test.each([
  [14, "day"], [15, "week"], [90, "week"], [91, "month"], [730, "month"], [731, "year"],
] as const)("Custom uses %s-day range with %s cells", (days, granularity) => {
  const start = new Date(2024, 0, 1);
  const end = new Date(start);
  end.setDate(end.getDate() + days);
  const result = getActivityHeatmap([], { startTimeSeconds: start.getTime() / 1000, endTimeSeconds: end.getTime() / 1000 }, SnapshotPeriod.CUSTOM);
  expect(result.granularity).toBe(granularity);
  expect(result.data.length).toBeGreaterThan(0);
  expect(result.data.every((cell) => cell.value === 0)).toBe(true);
});

