// Generated by Codex and not thoroughly checked for correctness.
test("open Custom ranges use history within the provided bound, while unavailable or reversed ranges stay empty", () => {
  const submissions = [
    { creationTimeSeconds: timestamp(2026, 9, 1) },
    { creationTimeSeconds: timestamp(2026, 9, 30) },
  ];
  const reference = new Date(2026, 9, 30, 12);
  const since = getActivityHeatmap(submissions, { startTimeSeconds: timestamp(2026, 9, 25) }, SnapshotPeriod.CUSTOM, reference);
  expect(since.data).toHaveLength(6);
  expect(since.data[5].value).toBe(1);
  const through = getActivityHeatmap(submissions, { endTimeSeconds: timestamp(2026, 9, 2) }, SnapshotPeriod.CUSTOM);
  expect(through.data).toHaveLength(1);
  expect(getActivityHeatmap(submissions, {}, SnapshotPeriod.CUSTOM, reference).granularity).toBe("week");
  expect(getActivityHeatmap([], {}, SnapshotPeriod.CUSTOM, reference).data).toEqual([]);
  expect(getActivityHeatmap([], { startTimeSeconds: 2000, endTimeSeconds: 1000 }, SnapshotPeriod.CUSTOM).data).toEqual([]);
});

// Generated by Codex and not thoroughly checked for correctness.
test("open Custom ranges retain the current partial year even when the last submission was in a previous year", () => {
  const result = getActivityHeatmap([
    { creationTimeSeconds: timestamp(2023, 5, 10) },
    { creationTimeSeconds: timestamp(2024, 11, 31) },
  ], {}, SnapshotPeriod.CUSTOM, new Date(2026, 9, 30, 12));
  expect(result.granularity).toBe("year");
  expect(result.data.map((cell) => cell.date.getFullYear())).toEqual([2023, 2024, 2025, 2026]);
  expect(result.data.map((cell) => cell.value)).toEqual([1, 1, 0, 0]);
  expect(result.data[1].label).toBe("Mon Jan 01 2024 – Tue Dec 31 2024: 1 submission · 1/366 active days");
  expect(result.data[3].label).toBe("Thu Jan 01 2026 – Fri Oct 30 2026: 0 submissions · 0/303 active days");
});

